     1→/**
     2→ * Bulk Upload Modal Component
     3→ *
     4→ * Modal for uploading recipient lists from CSV/Excel files
     5→ * Supports basic mode (phone + name) and variables mode (with template variables)
     6→ * Based on Figma design node-id: 77-3403
     7→ */
     8→
     9→import React, { useState, useEffect } from 'react';
    10→import { Modal, Button, Alert, Form } from 'react-bootstrap';
    11→import { X, Upload, Download, ExclamationTriangle } from 'react-bootstrap-icons';
    12→import campaignService from '../../services/campaignService';
    13→
    14→const BulkUploadModal = ({
    15→  show,
    16→  onHide,
    17→  onUpload,
    18→  selectedTemplate = null // Template object with variables array
    19→}) => {
    20→  const [selectedFile, setSelectedFile] = useState(null);
    21→  const [fileName, setFileName] = useState('');
    22→  const [uploading, setUploading] = useState(false);
    23→  const [error, setError] = useState(null);
    24→  const [parsedCount, setParsedCount] = useState(0);
    25→  const [duplicatesRemoved, setDuplicatesRemoved] = useState(0);
    26→
    27→  // New states for variable mode
    28→  const [uploadMode, setUploadMode] = useState('basic'); // 'basic' | 'with_variables'
    29→  const [selectedVariables, setSelectedVariables] = useState([]); // Array of variable names to include
    30→  const [validationErrors, setValidationErrors] = useState([]); // Errors from parsing
    31→
    32→  // Get template variables if available
    33→  const templateVariables = selectedTemplate?.variables || [];
    34→  const hasTemplateVariables = templateVariables.length > 0;
    35→
    36→  // Reset states when modal opens/closes
    37→  useEffect(() => {
    38→    if (show) {
    39→      // Reset to basic mode when opening
    40→      setUploadMode('basic');
    41→      setSelectedVariables([]);
    42→      setValidationErrors([]);
    43→    } else {
    44→      // Full reset when closing
    45→      setSelectedFile(null);
    46→      setFileName('');
    47→      setError(null);
    48→      setParsedCount(0);
    49→      setDuplicatesRemoved(0);
    50→      setUploadMode('basic');
    51→      setSelectedVariables([]);
    52→      setValidationErrors([]);
    53→    }
    54→  }, [show]);
    55→
    56→  // When switching to variables mode, select all variables by default
    57→  useEffect(() => {
    58→    if (uploadMode === 'with_variables' && templateVariables.length > 0) {
    59→      setSelectedVariables(templateVariables.map(v => v.name));
    60→    } else if (uploadMode === 'basic') {
    61→      setSelectedVariables([]);
    62→    }
    63→  }, [uploadMode, templateVariables]);
    64→
    65→  const handleFileSelect = (e) => {
    66→    const file = e.target.files[0];
    67→    if (file) {
    68→      // Validate file type
    69→      const validTypes = [
    70→        'text/csv',
    71→        'application/vnd.ms-excel',
    72→        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    73→        'text/plain'
    74→      ];
    75→
    76→      if (!validTypes.includes(file.type) && !file.name.match(/\.(csv|xlsx|xls|txt)$/i)) {
    77→        setError('Formato de archivo no válido. Use CSV, XLSX o TXT');
    78→        return;
    79→      }
    80→
    81→      setSelectedFile(file);
    82→      setFileName(file.name);
    83→      setError(null);
    84→      setParsedCount(0);
    85→      setValidationErrors([]);
    86→    }
    87→  };
    88→
    89→  const handleRemoveFile = () => {
    90→    setSelectedFile(null);
    91→    setFileName('');
    92→    setError(null);
    93→    setParsedCount(0);
    94→    setDuplicatesRemoved(0);
    95→    setValidationErrors([]);
    96→  };
    97→
    98→  const handleVariableToggle = (varName) => {
    99→    setSelectedVariables(prev => {
   100→      if (prev.includes(varName)) {
   101→        return prev.filter(v => v !== varName);
   102→      } else {
   103→        return [...prev, varName];
   104→      }
   105→    });
   106→  };
   107→
   108→  const handleUpload = async () => {
   109→    if (!selectedFile) {
   110→      setError('Seleccione un archivo primero');
   111→      return;
   112→    }
   113→
   114→    // Validate that at least one variable is selected if in variables mode
   115→    if (uploadMode === 'with_variables' && selectedVariables.length === 0) {
   116→      setError('Debe seleccionar al menos una variable para incluir en el Excel');
   117→      return;
   118→    }
   119→
   120→    setUploading(true);
   121→    setError(null);
   122→    setValidationErrors([]);
   123→
   124→    try {
   125→      // Parse the file with or without expected variables
   126→      const expectedVars = uploadMode === 'with_variables' ? selectedVariables : [];
   127→      const result = await campaignService.parseRecipientsFile(selectedFile, expectedVars);
   128→
   129→      const { recipients, errors } = result;
   130→
   131→      console.log('Parsed recipients:', recipients);
   132→      console.log('Validation errors:', errors);
   133→
   134→      if (recipients.length === 0) {
   135→        setError('El archivo no contiene números válidos');
   136→        setUploading(false);
   137→        return;
   138→      }
   139→
   140→      // If there are validation errors (empty variables), show them and block
   141→      if (errors.length > 0) {
   142→        setValidationErrors(errors);
   143→        setError(`Se encontraron ${errors.length} fila(s) con variables vacías. Todas las variables deben estar completas.`);
   144→        setUploading(false);
   145→        return;
   146→      }
   147→
   148→      // Clean and validate phone numbers
   149→      const validRecipients = recipients.map(r => ({
   150→        ...r,
   151→        phone: r.phone.replace(/\s+/g, '') // Remove all spaces
   152→      })).filter(r => {
   153→        // Allow + followed by country code and 6-15 digits
   154→        const phoneRegex = /^\+[1-9]\d{5,14}$/;
   155→        return phoneRegex.test(r.phone);
   156→      });
   157→
   158→      if (validRecipients.length === 0) {
   159→        setError('Ningún número tiene formato válido. Use formato internacional: +57 3001234567');
   160→        setUploading(false);
   161→        return;
   162→      }
   163→
   164→      // Remove duplicates based on phone number
   165→      const uniqueRecipients = [];
   166→      const seenPhones = new Set();
   167→      let duplicatesCount = 0;
   168→
   169→      for (const recipient of validRecipients) {
   170→        if (!seenPhones.has(recipient.phone)) {
   171→          seenPhones.add(recipient.phone);
   172→          uniqueRecipients.push(recipient);
   173→        } else {
   174→          duplicatesCount++;
   175→        }
   176→      }
   177→
   178→      setParsedCount(uniqueRecipients.length);
   179→      setDuplicatesRemoved(duplicatesCount);
   180→
   181→      // Build warning message
   182→      const warnings = [];
   183→      const invalidCount = recipients.length - validRecipients.length;
   184→      if (invalidCount > 0) {
   185→        warnings.push(`${invalidCount} número(s) con formato inválido fueron omitidos`);
   186→      }
   187→      if (duplicatesCount > 0) {
   188→        warnings.push(`${duplicatesCount} número(s) duplicado(s) fueron eliminados`);
   189→      }
   190→
   191→      if (warnings.length > 0) {
   192→        setError(warnings.join('. '));
   193→      }
   194→
   195→      // Call parent callback with unique recipients and the selected variable names
   196→      onUpload(uniqueRecipients, uploadMode === 'with_variables' ? selectedVariables : []);
   197→
   198→      // Reset and close
   199→      handleClose();
   200→
   201→    } catch (err) {
   202→      setError(err.message || 'Error al procesar el archivo');
   203→    } finally {
   204→      setUploading(false);
   205→    }
   206→  };
   207→
   208→  const handleDownloadTemplate = () => {
   209→    try {
   210→      // If in variables mode, pass the selected variables
   211→      if (uploadMode === 'with_variables' && selectedVariables.length > 0) {
   212→        // Get the full variable objects for the selected ones
   213→        const variablesToInclude = templateVariables.filter(v =>
   214→          selectedVariables.includes(v.name)
   215→        );
   216→        campaignService.downloadTemplate(variablesToInclude);
   217→      } else {
   218→        campaignService.downloadTemplate();
   219→      }
   220→    } catch (err) {
   221→      setError('Error al descargar la plantilla');
   222→    }
   223→  };
   224→
   225→  const handleClose = () => {
   226→    setSelectedFile(null);
   227→    setFileName('');
   228→    setError(null);
   229→    setParsedCount(0);
   230→    setDuplicatesRemoved(0);
   231→    setUploadMode('basic');
   232→    setSelectedVariables([]);
   233→    setValidationErrors([]);
   234→    setUploading(false);
   235→    onHide();
   236→  };
   237→
   238→  // Check if can use variables mode
   239→  const canUseVariablesMode = selectedTemplate && hasTemplateVariables;
   240→
   241→  // Check if upload is allowed
   242→  const canUpload = selectedFile &&
   243→    (uploadMode === 'basic' || (uploadMode === 'with_variables' && selectedVariables.length > 0));
   244→
   245→  return (
   246→    <Modal show={show} onHide={handleClose} size="lg" scrollable>
   247→      <Modal.Header className="border-0 pb-0">
   248→        <Modal.Title className="fs-4">Carga masiva</Modal.Title>
   249→        <Button
   250→          variant="link"
   251→          className="text-dark p-0"
   252→          onClick={handleClose}
   253→        >
   254→          <X size={24} />
   255→        </Button>
   256→      </Modal.Header>
   257→
   258→      <Modal.Body>
   259→        <div className="mb-4">
   260→          {/* Upload Mode Selection */}
   261→          <div className="mb-4">
   262→            <p className="fw-bold text-dark mb-2">Tipo de carga:</p>
   263→            <Form.Check
   264→              type="radio"
   265→              id="mode-basic"
   266→              name="uploadMode"
   267→              label="Solo contactos (teléfono y nombre)"
   268→              checked={uploadMode === 'basic'}
   269→              onChange={() => setUploadMode('basic')}
   270→              className="mb-2"
   271→            />
   272→            <Form.Check
   273→              type="radio"
   274→              id="mode-variables"
   275→              name="uploadMode"
   276→              label="Con variables de plantilla"
   277→              checked={uploadMode === 'with_variables'}
   278→              onChange={() => setUploadMode('with_variables')}
   279→              disabled={!canUseVariablesMode}
   280→            />
   281→            {!canUseVariablesMode && (
   282→              <small className="text-muted d-block mt-1 ms-4">
   283→                {!selectedTemplate
   284→                  ? 'Primero seleccione una plantilla en el formulario'
   285→                  : 'La plantilla seleccionada no tiene variables'}
   286→              </small>
   287→            )}
   288→          </div>
   289→
   290→          {/* Variable Selection (only shown in variables mode) */}
   291→          {uploadMode === 'with_variables' && hasTemplateVariables && (
   292→            <div className="mb-4 p-3 border rounded bg-light">
   293→              <p className="fw-bold text-dark mb-2">Variables a incluir en el Excel:</p>
   294→              <small className="text-muted d-block mb-3">
   295→                Selecciona las variables que deseas completar desde el Excel.
   296→                Las variables no seleccionadas se completarán manualmente en el formulario.
   297→              </small>
   298→
   299→              {templateVariables.map(variable => (
   300→                <Form.Check
   301→                  key={variable.name}
   302→                  type="checkbox"
   303→                  id={`var-${variable.name}`}
   304→                  label={
   305→                    <span>
   306→                      <strong>{variable.name}</strong>
   307→                      {variable.example && (
   308→                        <span className="text-muted ms-2">(ej: {variable.example})</span>
   309→                      )}
   310→                    </span>
   311→                  }
   312→                  checked={selectedVariables.includes(variable.name)}
   313→                  onChange={() => handleVariableToggle(variable.name)}
   314→                  className="mb-2"
   315→                />
   316→              ))}
   317→
   318→              {selectedVariables.length === 0 && (
   319→                <Alert variant="warning" className="py-2 mt-2 mb-0">
   320→                  <ExclamationTriangle className="me-2" />
   321→                  <small>Debe seleccionar al menos una variable</small>
   322→                </Alert>
   323→              )}
   324→
   325→              {selectedVariables.length > 0 && selectedVariables.length < templateVariables.length && (
   326→                <Alert variant="info" className="py-2 mt-2 mb-0">
   327→                  <small>
   328→                    {templateVariables.length - selectedVariables.length} variable(s) se completarán manualmente en el formulario
   329→                  </small>
   330→                </Alert>
   331→              )}
   332→            </div>
   333→          )}
   334→
   335→          {/* Download Template Button */}
   336→          <div className="mb-3 d-flex justify-content-between align-items-center">
   337→            <h6 className="mb-0 text-dark">Plantilla de carga</h6>
   338→            <Button
   339→              variant="outline-success"
   340→              size="sm"
   341→              onClick={handleDownloadTemplate}
   342→              disabled={uploading || (uploadMode === 'with_variables' && selectedVariables.length === 0)}
   343→            >
   344→              <Download className="me-2" size={16} />
   345→              Descargar plantilla Excel
   346→            </Button>
   347→          </div>
   348→
   349→          <Alert variant="info" className="py-2 mb-3">
   350→            <small>
   351→              <strong>Recomendación:</strong> Descarga la plantilla Excel, llénala con tus datos y súbela aquí.
   352→              La plantilla ya tiene el formato correcto con ejemplos.
   353→            </small>
   354→          </Alert>
   355→
   356→          <div className="text-muted mb-3" style={{ lineHeight: 1.5 }}>
   357→            <p className="mb-2 fw-bold">Formato del archivo:</p>
   358→            <ul className="mb-2">
   359→              <li>Primera columna: <strong>Número de Teléfono</strong> (obligatorio) - Debe incluir el prefijo internacional, por ejemplo: <strong>+34 612345678</strong> o <strong>+57 334 5678463</strong></li>
   360→              <li>Segunda columna: <strong>Nombre</strong> (opcional) - Nombre del contacto</li>
   361→              {uploadMode === 'with_variables' && selectedVariables.length > 0 && (
   362→                <li>Columnas adicionales: <strong>{selectedVariables.join(', ')}</strong> (obligatorias)</li>
   363→              )}
   364→              <li>Primera fila: Encabezados (será ignorada automáticamente)</li>
   365→            </ul>
   366→            <p className="mb-2">
   367→              Formatos soportados: .csv, .xlsx o .txt
   368→            </p>
   369→          </div>
   370→
   371→          {/* File Input */}
   372→          <div className="d-flex align-items-stretch">
   373→            <Button
   374→              variant="outline-primary"
   375→              className="rounded-end-0"
   376→              onClick={() => document.getElementById('file-input').click()}
   377→              disabled={uploading}
   378→            >
   379→              Elegir archivo
   380→            </Button>
   381→            <Form.Control
   382→              id="file-input"
   383→              type="file"
   384→              accept=".csv,.xlsx,.xls,.txt"
   385→              onChange={handleFileSelect}
   386→              className="d-none"
   387→            />
   388→            <div className="flex-grow-1 border border-start-0 rounded-end px-3 d-flex align-items-center justify-content-between">
   389→              {fileName ? (
   390→                <>
   391→                  <span className="text-muted">{fileName}</span>
   392→                  <Button
   393→                    variant="link"
   394→                    size="sm"
   395→                    className="text-danger p-0"
   396→                    onClick={handleRemoveFile}
   397→                  >
   398→                    <X size={20} />
   399→                  </Button>
   400→                </>
   401→              ) : (
   402→                <span className="text-muted">Ningún archivo seleccionado</span>
   403→              )}
   404→            </div>
   405→          </div>
   406→
   407→          {parsedCount > 0 && (
   408→            <Alert variant="success" className="mt-3 py-2 mb-0">
   409→              <small>
   410→                Se encontraron {parsedCount} número(s) válido(s) en el archivo
   411→                {duplicatesRemoved > 0 && ` (${duplicatesRemoved} duplicado(s) eliminados)`}
   412→              </small>
   413→            </Alert>
   414→          )}
   415→
   416→          {/* Validation Errors Display */}
   417→          {validationErrors.length > 0 && (
   418→            <Alert variant="danger" className="mt-3 py-2 mb-0">
   419→              <p className="mb-2 fw-bold">
   420→                <ExclamationTriangle className="me-2" />
   421→                Errores de validación ({validationErrors.length}):
   422→              </p>
   423→              <div style={{ maxHeight: '150px', overflowY: 'auto' }}>
   424→                <ul className="mb-0 small">
   425→                  {validationErrors.slice(0, 10).map((err, idx) => (
   426→                    <li key={idx}>
   427→                      Fila {err.row} ({err.phone}): {err.message}
   428→                    </li>
   429→                  ))}
   430→                  {validationErrors.length > 10 && (
   431→                    <li className="text-muted">
   432→                      ... y {validationErrors.length - 10} error(es) más
   433→                    </li>
   434→                  )}
   435→                </ul>
   436→              </div>
   437→            </Alert>
   438→          )}
   439→
   440→          {error && validationErrors.length === 0 && (
   441→            <Alert variant="warning" className="mt-3 py-2 mb-0">
   442→              <small>{error}</small>
   443→            </Alert>
   444→          )}
   445→        </div>
   446→      </Modal.Body>
   447→
   448→      <Modal.Footer className="border-0">
   449→        <Button variant="outline-dark" onClick={handleClose} disabled={uploading}>
   450→          Volver
   451→        </Button>
   452→        <Button
   453→          variant="warning"
   454→          onClick={handleUpload}
   455→          disabled={!canUpload || uploading}
   456→        >
   457→          {uploading ? (
   458→            <>
   459→              <span className="spinner-border spinner-border-sm me-2" />
   460→              Procesando...
   461→            </>
   462→          ) : (
   463→            <>
   464→              <Upload className="me-2" size={16} />
   465→              Cargar receptores
   466→            </>
   467→          )}
   468→        </Button>
   469→      </Modal.Footer>
   470→    </Modal>
   471→  );
   472→};
   473→
   474→export default BulkUploadModal;
   475→

