   392→    // Update which variables come from Excel
   393→    setExcelVariables(variablesFromExcel);
   394→
   395→    setFormData(prev => {
   396→      // Combine existing and new recipients
   397→      const allRecipients = [...prev.recipients, ...recipients];
   398→
   399→      // Remove duplicates based on phone number
   400→      const uniqueRecipients = [];
   401→      const seenPhones = new Set();
   402→
   403→      for (const recipient of allRecipients) {
   404→        if (!seenPhones.has(recipient.phone)) {
   405→          seenPhones.add(recipient.phone);
   406→          uniqueRecipients.push(recipient);
   407→        }
   408→      }
   409→
   410→      // Calculate how many duplicates were removed
   411→      const duplicatesRemoved = allRecipients.length - uniqueRecipients.length;
   412→
   413→      // Show notification if duplicates were removed
   414→      if (duplicatesRemoved > 0) {
   415→        setErrors(prevErrors => ({
   416→          ...prevErrors,
   417→          recipients: `Se eliminaron ${duplicatesRemoved} número(s) duplicado(s)`
   418→        }));
   419→        // Clear the error after 5 seconds
   420→        setTimeout(() => {
   421→          setErrors(prevErrors => {
   422→            const newErrors = { ...prevErrors };
   423→            delete newErrors.recipients;
   424→            return newErrors;
   425→          });
   426→        }, 5000);
   427→      }
   428→
   429→      // Clear manual values for variables that now come from Excel
   430→      const updatedTemplateVariables = { ...prev.templateVariables };
   431→      variablesFromExcel.forEach(varName => {
   432→        updatedTemplateVariables[varName] = ''; // Clear manual value
   433→      });
   434→
   435→      return {
   436→        ...prev,
   437→        recipients: uniqueRecipients,
   438→        templateVariables: updatedTemplateVariables
   439→      };
   440→    });
   441→    setShowBulkUpload(false);
   442→  };
