   957→                {/* Only show manual input for variables NOT in excelVariables */}
   958→                {selectedTemplate.variables
   959→                  .filter(variable => !excelVariables.includes(variable.name))
   960→                  .map(variable => (
   961→                  <Row key={variable.name} className="mb-3 align-items-center">
   962→                    <Col md={4}>
