   964→                    </Col>
   965→                    <Col md={8}>
   966→                      <Form.Group>
   967→                        <Form.Control
   968→                          type="text"
   969→                          placeholder={variable.example ? `Ej: ${variable.example}` : `Especifica ${variable.name.toLowerCase()}`}
   970→                          value={formData.templateVariables[variable.name] || ''}
   971→                          onChange={(e) => handleVariableChange(variable.name, e.target.value)}
   972→                          isInvalid={!!errors[`var_${variable.name}`]}
   973→                        />
   974→                        <Form.Control.Feedback type="invalid">
