   976→                        </Form.Control.Feedback>
   977→                      </Form.Group>
   978→                    </Col>
   979→                  </Row>
   980→                ))}
   981→              </div>
   982→            )}
   983→
   984→            {/* Button Parameters */}
   985→            {formData.buttonParams && formData.buttonParams.length > 0 && (
   986→              <div className="mb-3">
   987→                <p className="fw-bold text-dark mb-2">Parámetros de botones</p>
   988→                <Alert variant="info" className="py-2">
   989→                  <small>
