   991→                  </small>
   992→                </Alert>
   993→                {formData.buttonParams.map((btnParam, idx) => (
   994→                  <Row key={idx} className="mb-3 align-items-center">
   995→                    <Col md={4}>
   996→                      <Form.Label className="mb-0">
   997→                        {btnParam.type === 'url' ? 'Sufijo URL dinámica' : 'Código del botón'}
   998→                      </Form.Label>
   999→                    </Col>
  1000→                    <Col md={8}>
  1001→                      <Form.Group>
  1002→                        <Form.Control
  1003→                          type="text"
  1004→                          placeholder={btnParam.type === 'url' ? 'Ej: parametro-dinamico' : 'Ej: CODIGO123'}
  1005→                          value={btnParam.type === 'url' ? btnParam.text : btnParam.code}
  1006→                          onChange={(e) => {
  1007→                            const newButtonParams = [...formData.buttonParams];
  1008→                            if (btnParam.type === 'url') {
  1009→                              newButtonParams[idx] = { ...btnParam, text: e.target.value };
  1010→                            } else {
  1011→                              newButtonParams[idx] = { ...btnParam, code: e.target.value };
  1012→                            }
  1013→                            setFormData(prev => ({ ...prev, buttonParams: newButtonParams }));
  1014→                          }}
  1015→                          isInvalid={!!errors[`btn_${idx}`]}
  1016→                        />
  1017→                        <Form.Control.Feedback type="invalid">
