  1027→            {/* Agent Assignment Section */}
  1028→            <div className="mb-3">
  1029→              <p className="fw-bold fs-5 text-dark mb-2">Asignación de agentes</p>
  1030→              <Alert variant="info" className="py-2">
  1031→                <small>
  1032→                  Asigna uno o más agentes para recibir las respuestas de esta campaña. Si no asignas ninguno, todos los agentes con acceso a la línea recibirán las respuestas.
  1033→                </small>
  1034→              </Alert>
  1035→              <Row className="mb-3">
  1036→                <Col md={12}>
