  1072→                                  setFormData(prev => ({
  1073→                                    ...prev,
  1074→                                    assignedUserIds: [...prev.assignedUserIds, agent.id]
  1075→                                  }));
  1076→                                } else {
  1077→                                  setFormData(prev => ({
  1078→                                    ...prev,
  1079→                                    assignedUserIds: prev.assignedUserIds.filter(id => id !== agent.id)
