  1099→            </div>
  1100→
  1101→            {/* Add Recipients Section */}
  1102→            <div className="mb-3">
  1103→              <div className="d-flex justify-content-between align-items-center mb-2">
  1104→                <p className="fw-bold fs-5 text-dark mb-0">Agregar receptores</p>
  1105→                <Button
  1106→                  variant="outline-primary"
