  1108→                  onClick={() => setShowBulkUpload(true)}
  1109→                >
  1110→                  <FileEarmarkExcel className="me-2" />
  1111→                  Carga masiva
  1112→                </Button>
  1113→              </div>
  1114→
  1115→              <Row className="mb-2">
  1116→                <Col md={5}>
  1117→                  <Form.Control
  1118→                    type="text"
  1119→                    placeholder="Nombre (Opcional)"
  1120→                    value={newRecipient.name}
