  1122→                  />
  1123→                </Col>
  1124→                <Col md={5}>
  1125→                  <Form.Control
  1126→                    type="text"
  1127→                    placeholder="Número de teléfono"
  1128→                    value={newRecipient.phone}
  1129→                    onChange={(e) => setNewRecipient(prev => ({ ...prev, phone: e.target.value }))}
  1130→                    isInvalid={!!errors.phone}
  1131→                  />
  1132→                  <Form.Control.Feedback type="invalid">
