  1146→            </div>
  1147→
  1148→            {/* Recipients Table */}
  1149→            {formData.recipients.length > 0 && (
  1150→              <div className="mb-3">
  1151→                <div className="table-responsive">
  1152→                  <Table striped bordered hover size="sm">
  1153→                  <thead className="bg-light">
  1154→                    <tr>
