  1184→            )}
  1185→
  1186→            {errors.recipients && (
  1187→              <Alert
  1188→                variant={errors.recipients.includes('duplicado') ? 'info' : 'danger'}
  1189→                className="py-2"
  1190→              >
  1191→                {errors.recipients}
