/**
 * Campaign Form Component
 *
 * Modal form for creating mass message campaigns
 * Based on Figma design node-id: 20-2464
 */

import React, { useState, useEffect, useCallback } from 'react';
import { Modal, Button, Form, Row, Col, Table, Alert } from 'react-bootstrap';
import { X, Send, Trash, FileEarmarkExcel } from 'react-bootstrap-icons';
import BulkUploadModal from './BulkUploadModal';
import useLinesStore from '../../store/linesStore';
import useTemplatesStore from '../../store/templatesStore';
import templateService from '../../services/templateService';
import userService from '../../services/userService';
import { getAuthToken } from '../../services/api';

const CampaignForm = ({ show, onHide, onSubmit, initialRecipients = [], loading = false }) => {

  const fetchLines = useLinesStore((state) => state.fetchLines);

  const setTemplates = useTemplatesStore((state) => state.setTemplates);
  const setLoading = useTemplatesStore((state) => state.setLoading);
  const setError = useTemplatesStore((state) => state.setError);

  const templates = useTemplatesStore((state) => state.templates);

  const lines = useLinesStore((state) => state.lines); 

  const getApprovedTemplatesByLine = useTemplatesStore(
    (state) => state.getApprovedTemplatesByLine
  );

  const [formData, setFormData] = useState({
    campaignName: '', // NUEVO CAMPO
    lineId: '',
    templateId: '',
    scheduledAt: '',
    recipients: [],
    templateVariables: {},
    headerParams: {},
    buttonParams: [],
    assignedUserIds: [],
    assignToSelf: false
  });

  const [newRecipient, setNewRecipient] = useState({
    name: '',
    phone: ''
  });

  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [showBulkUpload, setShowBulkUpload] = useState(false);
  const [errors, setErrors] = useState({});
  const [bodyCharCount, setBodyCharCount] = useState(0);

  const [availableTemplates, setAvailableTemplates] = useState([]);
  const [availableAgents, setAvailableAgents] = useState([]);

  // Media upload states
  const [uploadingMedia, setUploadingMedia] = useState(false);
  const [uploadedMedia, setUploadedMedia] = useState(null);
  const [mediaUploadError, setMediaUploadError] = useState(null);
  const [headerCaption, setHeaderCaption] = useState('');

  // Excel variables state - tracks which variables are filled from Excel
  const [excelVariables, setExcelVariables] = useState([]);

  // Calcular el conteo de caracteres del body con las variables reemplazadas
  const calculateBodyCharCount = useCallback((template, templateVariables) => {
    if (!template || !template.content) return 0;

    let finalContent = template.content;

    // Reemplazar cada variable con su valor real
    if (template.variables && Array.isArray(template.variables)) {
      template.variables.forEach((variable, index) => {
        const placeholder = `{{${index + 1}}}`;
        const realValue = templateVariables[variable.name] || '';
        finalContent = finalContent.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), realValue);
      });
    }

    return finalContent.length;
  }, []);

  const loadTemplates = useCallback(async () => {
    if (!setLoading) return; 

    try {
      setLoading(true);
      const response = await templateService.getTemplates(); 

      setTemplates(response.data.templates);
      if (setError) setError(null);

    } catch (err) {
      console.error("Error cargando plantillas:", err);
      if (setError) setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [setLoading, setTemplates, setError]);

  useEffect(() => {
    if (show) {
      fetchLines();

      loadTemplates();

      if (initialRecipients.length > 0) {
        setFormData(prev => ({
          ...prev,
          recipients: initialRecipients
        }));
      }
    } else {
      // Reset form when modal is closed
      setFormData({
        campaignName: '',
        lineId: '',
        templateId: '',
        scheduledAt: '',
        recipients: [],
        templateVariables: {},
        headerParams: {},
        buttonParams: [],
        assignedUserIds: [],
        assignToSelf: false
      });
      setNewRecipient({ name: '', phone: '' });
      setSelectedTemplate(null);
      setAvailableAgents([]);
      setErrors({});
      setUploadedMedia(null);
      setUploadingMedia(false);
      setMediaUploadError(null);
      setHeaderCaption('');
      setBodyCharCount(0);
      setExcelVariables([]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [show, initialRecipients]);

  useEffect(() => {
    if (formData.lineId) {
      const numericLineId = parseInt(formData.lineId, 10);
      const filtered = getApprovedTemplatesByLine(numericLineId);
      setAvailableTemplates(filtered);

      // Load agents for selected line
      const loadAgents = async () => {
        try {
          const response = await userService.getAgentsByLine(numericLineId);
          setAvailableAgents(response.data || []);
        } catch (error) {
          console.error('Error loading agents:', error);
          setAvailableAgents([]);
        }
      };
      loadAgents();
    } else {
      setAvailableTemplates([]);
      setAvailableAgents([]);
    }
  }, [formData.lineId, getApprovedTemplatesByLine, templates]);

  useEffect(() => {
    if (formData.templateId) {
      const template = availableTemplates.find(t => t.id === parseInt(formData.templateId));

      // Initialize template variables
      if (template) {
        const vars = {};
        let variableList = [];

        if (template.variables && typeof template.variables === 'string') {
          variableList = JSON.parse(template.variables);
        } else if (Array.isArray(template.variables)) {
          variableList = template.variables;
        }

        const templateParsed = { ...template, variables: variableList  };

        setSelectedTemplate(templateParsed);

        variableList.forEach(v => {
          vars[v.name] = '';
        });

        // Initialize header params
        const newHeaderParams = {};
        if (template.header_type === 'TEXT' && template.header_content?.includes('{{1}}')) {
          newHeaderParams.text = '';
        }

        // Initialize button params
        const buttons = typeof template.buttons === 'string'
          ? JSON.parse(template.buttons)
          : template.buttons || [];

        const newButtonParams = [];
        buttons.forEach((btn, index) => {
          if (btn.type === 'URL' && btn.url?.includes('{{1}}')) {
            newButtonParams.push({ index, type: 'url', text: '' });
          } else if (btn.type === 'COPY_CODE') {
            newButtonParams.push({ index, type: 'copy_code', code: '' });
          }
        });

        // Load header caption from template
        setHeaderCaption(template.header_caption || '');

        // Clear excel variables when template changes (recipients need to be re-uploaded)
        setExcelVariables([]);

        setFormData(prev => ({
          ...prev,
          templateVariables: vars,
          headerParams: newHeaderParams,
          buttonParams: newButtonParams,
          recipients: [] // Clear recipients when template changes
        }));

        // Calcular el contador inicial
        setBodyCharCount(calculateBodyCharCount(templateParsed, vars));
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [formData.templateId]);

  // Recalcular el contador cuando cambian las variables
  useEffect(() => {
    if (selectedTemplate) {
      setBodyCharCount(calculateBodyCharCount(selectedTemplate, formData.templateVariables));
    }
  }, [formData.templateVariables, selectedTemplate, calculateBodyCharCount]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    setErrors(prev => ({ ...prev, [name]: null }));
  };

  const handleVariableChange = (varName, value) => {
    setFormData(prev => ({
      ...prev,
      templateVariables: {
        ...prev.templateVariables,
        [varName]: value
      }
    }));
  };

  const fillExampleValues = () => {
    if (!selectedTemplate || !selectedTemplate.variables) return;

    const exampleValues = {};
    selectedTemplate.variables.forEach(variable => {
      exampleValues[variable.name] = variable.example || '';
    });

    setFormData(prev => ({
      ...prev,
      templateVariables: exampleValues
    }));
  };

  const clearVariableValues = () => {
    if (!selectedTemplate || !selectedTemplate.variables) return;

    const emptyValues = {};
    selectedTemplate.variables.forEach(variable => {
      emptyValues[variable.name] = '';
    });

    setFormData(prev => ({
      ...prev,
      templateVariables: emptyValues
    }));
  };

  const handleMediaUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file || !formData.lineId || !selectedTemplate) return;

    setUploadingMedia(true);
    setMediaUploadError(null);

    try {
      const formDataUpload = new FormData();
      formDataUpload.append('file', file);
      formDataUpload.append('lineId', formData.lineId);
      formDataUpload.append('mediaType', selectedTemplate.header_type.toLowerCase());

      const apiUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api/v1';
      const token = getAuthToken();

      if (!token) {
        throw new Error('No está autenticado. Por favor inicie sesión nuevamente.');
      }

      const response = await fetch(`${apiUrl}/messages/upload-message-media`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`
        },
        body: formDataUpload
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Error al subir el archivo');
      }

      const result = await response.json();
      setUploadedMedia(result.data);

      // Update headerParams with the uploaded file's public URL and original filename
      const mediaType = selectedTemplate.header_type.toLowerCase();
      setFormData(prev => ({
        ...prev,
        headerParams: {
          ...prev.headerParams,
          [mediaType]: {
            link: result.data.publicUrl,
            filename: result.data.originalName // Include original filename
          }
        }
      }));

    } catch (error) {
      console.error('Error uploading media:', error);
      setMediaUploadError(error.message);
    } finally {
      setUploadingMedia(false);
      e.target.value = ''; // Reset file input
    }
  };

  const handleRemoveMedia = () => {
    setUploadedMedia(null);
    const mediaType = selectedTemplate.header_type.toLowerCase();
    setFormData(prev => ({
      ...prev,
      headerParams: {
        ...prev.headerParams,
        [mediaType]: undefined
      }
    }));
  };

  const handleAddRecipient = () => {
    if (!newRecipient.phone.trim()) {
      setErrors(prev => ({ ...prev, phone: 'Número de teléfono requerido' }));
      return;
    }

    // Validate phone format (E.164)
    const phoneRegex = /^\+[1-9]\d{1,14}$/;
    if (!phoneRegex.test(newRecipient.phone)) {
      setErrors(prev => ({
        ...prev,
        phone: 'Formato inválido. Use formato internacional: +57 3001234567'
      }));
      return;
    }

    // Check for duplicates
    if (formData.recipients.some(r => r.phone === newRecipient.phone)) {
      setErrors(prev => ({ ...prev, phone: 'Este número ya fue agregado' }));
      return;
    }

    setFormData(prev => ({
      ...prev,
      recipients: [...prev.recipients, { ...newRecipient }]
    }));

    setNewRecipient({ name: '', phone: '' });
    setErrors(prev => ({ ...prev, phone: null }));
  };

  const handleRemoveRecipient = (phone) => {
    setFormData(prev => ({
      ...prev,
      recipients: prev.recipients.filter(r => r.phone !== phone)
    }));
  };

  const handleBulkUpload = (recipients, variablesFromExcel = []) => {
    // Update which variables come from Excel
    setExcelVariables(variablesFromExcel);

    setFormData(prev => {
      // Combine existing and new recipients
      const allRecipients = [...prev.recipients, ...recipients];

      // Remove duplicates based on phone number
      const uniqueRecipients = [];
      const seenPhones = new Set();

      for (const recipient of allRecipients) {
        if (!seenPhones.has(recipient.phone)) {
          seenPhones.add(recipient.phone);
          uniqueRecipients.push(recipient);
        }
      }

      // Calculate how many duplicates were removed
      const duplicatesRemoved = allRecipients.length - uniqueRecipients.length;

      // Show notification if duplicates were removed
      if (duplicatesRemoved > 0) {
        setErrors(prevErrors => ({
          ...prevErrors,
          recipients: `Se eliminaron ${duplicatesRemoved} número(s) duplicado(s)`
        }));
        // Clear the error after 5 seconds
        setTimeout(() => {
          setErrors(prevErrors => {
            const newErrors = { ...prevErrors };
            delete newErrors.recipients;
            return newErrors;
          });
        }, 5000);
      }

      // Clear manual values for variables that now come from Excel
      const updatedTemplateVariables = { ...prev.templateVariables };
      variablesFromExcel.forEach(varName => {
        updatedTemplateVariables[varName] = ''; // Clear manual value
      });

      return {
        ...prev,
        recipients: uniqueRecipients,
        templateVariables: updatedTemplateVariables
      };
    });
    setShowBulkUpload(false);
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.campaignName.trim()) { // NUEVA VALIDACIÓN
      newErrors.campaignName = 'El nombre de la campaña es obligatorio';
    }

    if (!formData.lineId) {
      newErrors.lineId = 'Seleccione una línea de negocio';
    }

    if (!formData.templateId) {
      newErrors.templateId = 'Seleccione una plantilla';
    }

    if (formData.recipients.length === 0) {
      newErrors.recipients = 'Agregue al menos un receptor';
    }

    // Validar que el body con variables no exceda 1024 caracteres
    if (bodyCharCount > 1024) {
      newErrors.bodyCharCount = 'El contenido con variables excede el límite de 1024 caracteres';
    }

    // Validate template variables (only those NOT filled from Excel)
    if (selectedTemplate?.variables) {
      selectedTemplate.variables.forEach(v => {
        // Skip validation for variables that come from Excel
        if (excelVariables.includes(v.name)) {
          return;
        }
        if (!formData.templateVariables[v.name]?.trim()) {
          newErrors[`var_${v.name}`] = `La variable "${v.name}" es requerida`;
        }
      });
    }

    // Validate header params
    if (selectedTemplate?.header_type === 'TEXT' && selectedTemplate.header_content?.includes('{{1}}')) {
      if (!formData.headerParams.text?.trim()) {
        newErrors.headerParams = 'El parámetro del encabezado es requerido';
      }
    } else if (selectedTemplate && ['IMAGE', 'VIDEO', 'DOCUMENT'].includes(selectedTemplate.header_type)) {
      // For media headers, only validate if there's NO default file
      const hasDefaultMedia = selectedTemplate.header_content && selectedTemplate.header_content.startsWith('http');
      const mediaType = selectedTemplate.header_type.toLowerCase();
      const hasCustomMedia = formData.headerParams[mediaType]?.link;

      if (!hasDefaultMedia && !hasCustomMedia) {
        newErrors.headerParams = `Debe proporcionar una URL para el ${
          selectedTemplate.header_type === 'IMAGE' ? 'imagen' :
          selectedTemplate.header_type === 'VIDEO' ? 'video' : 'documento'
        }`;
      }
    }

    // Validate button params
    if (formData.buttonParams && formData.buttonParams.length > 0) {
      formData.buttonParams.forEach((btnParam, idx) => {
        if (btnParam.type === 'url' && !btnParam.text?.trim()) {
          newErrors[`btn_${idx}`] = 'El parámetro del botón URL es requerido';
        }
        if (btnParam.type === 'copy_code' && !btnParam.code?.trim()) {
          newErrors[`btn_${idx}`] = 'El código del botón es requerido';
        }
      });
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = () => {
    if (!validateForm()) {
      return;
    }

    // Include header caption if present
    const submitData = {
      ...formData,
      headerCaption: headerCaption || null,
      excelVariableNames: excelVariables // Include which variables come from Excel
    };

    // Convert scheduledAt to ISO string with timezone if present
    // datetime-local returns format: "YYYY-MM-DDThh:mm" without timezone
    // We need to convert it to ISO format with user's timezone
    if (submitData.scheduledAt) {
      // Create a Date object from the datetime-local value
      // This interprets the date in the user's local timezone
      const localDate = new Date(submitData.scheduledAt);

      // Convert to ISO string (includes timezone as UTC)
      submitData.scheduledAt = localDate.toISOString();

      console.log('[CampaignForm] Scheduled date conversion:');
      console.log('  - Input (local):', formData.scheduledAt);
      console.log('  - Output (ISO):', submitData.scheduledAt);
      console.log('  - User timezone offset (minutes):', localDate.getTimezoneOffset());
    }

    onSubmit(submitData);
  };

  const handleClose = () => {
    setFormData({
      campaignName: '', // RESETEAR CAMPO
      lineId: '',
      templateId: '',
      scheduledAt: '',
      recipients: [],
      templateVariables: {},
      headerParams: {},
      buttonParams: [],
      assignedUserIds: [],
      assignToSelf: false
    });
    setNewRecipient({ name: '', phone: '' });
    setSelectedTemplate(null);
    setAvailableAgents([]);
    setErrors({});
    setUploadedMedia(null);
    setUploadingMedia(false);
    setMediaUploadError(null);
    setHeaderCaption('');
    setBodyCharCount(0);
    setExcelVariables([]);
    onHide();
  };

  const renderTemplatePreview = () => {
    if (!selectedTemplate) return null;

    let preview = selectedTemplate.content;
    Object.keys(formData.templateVariables).forEach(key => {
      const value = formData.templateVariables[key] || `(${key})`;
      preview = preview.replace(new RegExp(`{{${key}}}`, 'g'), value);
    });

    return (
      <div className="template-preview">
        <div className="d-flex justify-content-between align-items-center mb-2">
          <p className="fw-bold text-dark mb-0">Previsualización del texto</p>
          <small className={bodyCharCount > 1024 ? 'text-danger fw-bold' : bodyCharCount > 950 ? 'text-warning' : 'text-muted'}>
            {bodyCharCount}/1024 caracteres
          </small>
        </div>
        <div className="text-muted" style={{ whiteSpace: 'pre-wrap' }}>
          {preview}
        </div>
        {bodyCharCount > 1024 && (
          <Alert variant="danger" className="mt-2 py-2">
            <i className="bi bi-exclamation-triangle me-2"></i>
            El contenido excede el límite de 1024 caracteres cuando se reemplazan las variables.
            Por favor, reduce el contenido de las variables.
          </Alert>
        )}
        {errors.bodyCharCount && (
          <div className="text-danger small mt-1">
            <i className="bi bi-exclamation-circle me-1"></i>
            {errors.bodyCharCount}
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      <Modal show={show} onHide={handleClose} size="lg" scrollable>
        <Modal.Header className="border-0 pb-0">
          <Modal.Title className="fs-4 fw-bold">Mensaje masivo</Modal.Title>
          <Button
            variant="link"
            className="text-dark p-0"
            onClick={handleClose}
          >
            <X size={24} />
          </Button>
        </Modal.Header>

        <Modal.Body>
          <Form>
            {/* NUEVO: Campo de Nombre de Campaña */}
            <div className="mb-3">
              <Form.Group>
                <Form.Label className="fw-bold">
                  Nombre de la Campaña <span className="text-danger">*</span>
                </Form.Label>
                <Form.Control
                  type="text"
                  name="campaignName"
                  placeholder="Ej: Contratación Noviembre"
                  value={formData.campaignName}
                  onChange={handleInputChange}
                  isInvalid={!!errors.campaignName}
                  maxLength={200}
                  className="py-2"
                />
                <Form.Control.Feedback type="invalid">
                  {errors.campaignName}
                </Form.Control.Feedback>
                <Form.Text className="text-muted">
                  Identificador único para esta campaña (máx. 200 caracteres)
                </Form.Text>
              </Form.Group>
            </div>

            {/* Line and Schedule Selection */}
            <Row className="mb-3">
              <Col md={6}>
                <Form.Group>
                  <Form.Select
                    name="lineId"
                    value={formData.lineId}
                    onChange={handleInputChange}
                    isInvalid={!!errors.lineId}
                    className="py-2"
                  >
                    <option value="">Línea de negocio</option>
                    {lines.filter(l => l.is_active).map(line => (
                      <option key={line.id} value={line.id}>
                        {line.company_name} - {line.phone_number}
                      </option>
                    ))}
                  </Form.Select>
                  <Form.Control.Feedback type="invalid">
                    {errors.lineId}
                  </Form.Control.Feedback>
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group>
                  <Form.Control
                    type="datetime-local"
                    name="scheduledAt"
                    value={formData.scheduledAt}
                    onChange={handleInputChange}
                    placeholder="Elegir fecha de envío (Opcional)"
                    className="py-2"
                  />
                </Form.Group>
              </Col>
            </Row>

            {/* Template Selection */}
            <div className="mb-3">
              <p className="fw-bold fs-5 text-dark mb-2">Plantilla</p>
              <Form.Group>
                <Form.Select
                  name="templateId"
                  value={formData.templateId}
                  onChange={handleInputChange}
                  isInvalid={!!errors.templateId}
                  className="py-2"
                >
                  <option value="">Plantilla de mensaje</option>
                  {availableTemplates.map(template => (
                    <option key={template.id} value={template.id}>
                      {template.name}
                    </option>
                  ))}
                </Form.Select>
                <Form.Control.Feedback type="invalid">
                  {errors.templateId}
                </Form.Control.Feedback>
              </Form.Group>
            </div>

            {/* Template Preview */}
            {selectedTemplate && (
              <div className="mb-3">
                {renderTemplatePreview()}
              </div>
            )}

            {/* Header Parameters */}
            {selectedTemplate?.header_type === 'TEXT' && selectedTemplate.header_content?.includes('{{1}}') && (
              <div className="mb-3">
                <p className="fw-bold text-dark mb-2">Parámetros del encabezado</p>
                <Alert variant="info" className="py-2">
                  <small>
                    Esta plantilla tiene un encabezado con parámetros dinámicos.
                  </small>
                </Alert>
                <Row className="mb-3 align-items-center">
                  <Col md={4}>
                    <Form.Label className="mb-0">Texto del encabezado</Form.Label>
                  </Col>
                  <Col md={8}>
                    <Form.Group>
                      <Form.Control
                        type="text"
                        placeholder="Especifica el texto para el encabezado"
                        value={formData.headerParams.text || ''}
                        onChange={(e) => setFormData(prev => ({
                          ...prev,
                          headerParams: { ...prev.headerParams, text: e.target.value }
                        }))}
                        isInvalid={!!errors.headerParams}
                      />
                      <Form.Control.Feedback type="invalid">
                        {errors.headerParams}
                      </Form.Control.Feedback>
                    </Form.Group>
                  </Col>
                </Row>
              </div>
            )}

            {/* Media Header Parameters (IMAGE, VIDEO, DOCUMENT) */}
            {selectedTemplate && ['IMAGE', 'VIDEO', 'DOCUMENT'].includes(selectedTemplate.header_type) && (
              <div className="mb-3">
                <p className="fw-bold text-dark mb-2">Encabezado multimedia</p>
                <Alert variant="info" className="py-2">
                  <small>
                    Esta plantilla incluye un {selectedTemplate.header_type === 'IMAGE' ? 'imagen' : selectedTemplate.header_type === 'VIDEO' ? 'video' : 'documento'} en el encabezado.
                    {selectedTemplate.header_content && selectedTemplate.header_content.startsWith('http')
                      ? ' Se usará el archivo predeterminado de la plantilla.'
                      : ' Debes subir un archivo o especificar una URL pública.'}
                  </small>
                </Alert>

                {mediaUploadError && (
                  <Alert variant="danger" className="py-2 mb-2">
                    {mediaUploadError}
                  </Alert>
                )}

                {/* File Upload Section */}
                {!uploadedMedia && (
                  <Form.Group className="mb-3">
                    <Form.Label>Subir archivo</Form.Label>
                    <Form.Control
                      type="file"
                      onChange={handleMediaUpload}
                      disabled={uploadingMedia || !formData.lineId}
                      accept={
                        selectedTemplate.header_type === 'IMAGE' ? 'image/jpeg,image/jpg,image/png' :
                        selectedTemplate.header_type === 'VIDEO' ? 'video/mp4,video/3gpp,video/quicktime' :
                        '.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.zip,.rar'
                      }
                    />
                    <Form.Text className="text-muted">
                      {!formData.lineId && 'Primero seleccione una línea de WhatsApp. '}
                      {selectedTemplate.header_type === 'IMAGE' && 'Formatos: JPG, PNG (max 5MB)'}
                      {selectedTemplate.header_type === 'VIDEO' && 'Formatos: MP4, 3GPP, MOV (max 16MB)'}
                      {selectedTemplate.header_type === 'DOCUMENT' && 'Formatos: PDF, Word, Excel, PowerPoint, TXT, CSV, ZIP, RAR (max 100MB)'}
                    </Form.Text>
                    {uploadingMedia && (
                      <div className="d-flex align-items-center mt-2">
                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                        <span>Subiendo archivo...</span>
                      </div>
                    )}
                  </Form.Group>
                )}

                {/* Uploaded File Display */}
                {uploadedMedia && (
                  <Alert variant="success" className="py-2 mb-3">
                    <div className="d-flex justify-content-between align-items-center">
                      <div>
                        <i className="bi bi-check-circle me-2"></i>
                        <strong>{uploadedMedia.originalName}</strong>
                        <small className="text-muted ms-2">
                          ({(uploadedMedia.size / 1024 / 1024).toFixed(2)} MB)
                        </small>
                      </div>
                      <Button
                        variant="link"
                        className="text-danger p-0"
                        onClick={handleRemoveMedia}
                      >
                        <i className="bi bi-trash"></i>
                      </Button>
                    </div>
                  </Alert>
                )}

                {/* Manual URL Input */}
                {!uploadedMedia && (
                  <>
                    <Form.Text className="text-muted d-block mb-2">
                      O ingresa manualmente una URL pública:
                    </Form.Text>
                    <Form.Group className="mb-3">
                      <Form.Control
                        type="url"
                        placeholder={`https://ejemplo.com/archivo.${selectedTemplate.header_type === 'IMAGE' ? 'jpg' : selectedTemplate.header_type === 'VIDEO' ? 'mp4' : 'pdf'}`}
                        value={
                          formData.headerParams[selectedTemplate.header_type.toLowerCase()]?.link || ''
                        }
                        onChange={(e) => {
                          const mediaType = selectedTemplate.header_type.toLowerCase();
                          setFormData(prev => ({
                            ...prev,
                            headerParams: {
                              ...prev.headerParams,
                              [mediaType]: e.target.value.trim() ? { link: e.target.value.trim() } : undefined
                            }
                          }));
                        }}
                        isInvalid={!!errors.headerParams}
                        disabled={uploadingMedia}
                      />
                      <Form.Control.Feedback type="invalid">
                        {errors.headerParams}
                      </Form.Control.Feedback>
                      <Form.Text className="text-muted">
                        {selectedTemplate.header_content && selectedTemplate.header_content.startsWith('http')
                          ? 'Dejar vacío para usar el archivo predeterminado de la plantilla'
                          : 'Proporciona una URL pública accesible'}
                      </Form.Text>
                    </Form.Group>
                  </>
                )}

                {/* Caption/Title Field */}
                <Form.Group className="mb-3">
                  <Form.Label>
                    {selectedTemplate.header_type === 'DOCUMENT' ? 'Título del documento' : 'Descripción'} (opcional)
                  </Form.Label>
                  <Form.Control
                    type="text"
                    value={headerCaption}
                    onChange={(e) => setHeaderCaption(e.target.value)}
                    placeholder={
                      selectedTemplate.header_type === 'DOCUMENT'
                        ? 'Ej: Contrato de prestación de servicios'
                        : `Descripción para la ${selectedTemplate.header_type === 'IMAGE' ? 'imagen' : 'video'}`
                    }
                    maxLength={1024}
                  />
                  <Form.Text className="text-muted">
                    {headerCaption && headerCaption === selectedTemplate.header_caption
                      ? 'Usando el título/descripción de la plantilla'
                      : 'Este título/descripción aparecerá junto al archivo en WhatsApp'}
                  </Form.Text>
                </Form.Group>
              </div>
            )}

            {/* Template Variables */}
            {selectedTemplate?.variables && selectedTemplate.variables.length > 0 && (
              <div className="mb-3">
                <div className="d-flex justify-content-between align-items-center mb-2">
                  <p className="fw-bold text-dark mb-0">Variables del cuerpo</p>
                  {/* Only show buttons if there are manual variables to fill */}
                  {selectedTemplate.variables.some(v => !excelVariables.includes(v.name)) && (
                    <div>
                      <Button
                        variant="outline-secondary"
                        size="sm"
                        onClick={fillExampleValues}
                        className="me-2"
                      >
                        <i className="bi bi-magic me-1"></i>
                        Llenar con ejemplos
                      </Button>
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={clearVariableValues}
                      >
                        <i className="bi bi-x-circle me-1"></i>
                        Limpiar
                      </Button>
                    </div>
                  )}
                </div>

                {/* Show info about Excel variables */}
                {excelVariables.length > 0 && (
                  <Alert variant="success" className="py-2 mb-2">
                    <small>
                      <i className="bi bi-file-earmark-excel me-1"></i>
                      <strong>{excelVariables.length} variable(s)</strong> se completarán desde el Excel:
                      {' '}{excelVariables.join(', ')}
                    </small>
                  </Alert>
                )}

                {/* Show info about manual variables only if there are some */}
                {selectedTemplate.variables.filter(v => !excelVariables.includes(v.name)).length > 0 && (
                  <Alert variant="warning" className="py-2">
                    <small>
                      {excelVariables.length > 0 ? (
                        <>
                          Las siguientes {selectedTemplate.variables.filter(v => !excelVariables.includes(v.name)).length} variable(s)
                          deben completarse manualmente (valor global para todos los receptores).
                        </>
                      ) : (
                        <>
                          Se han identificado {selectedTemplate.variables.length} variables.
                          Especifica el valor correspondiente a cada una de ellas.
                          Ejemplo: Cargo: Diseñador.
                        </>
                      )}
                    </small>
                  </Alert>
                )}

                {/* All variables come from Excel */}
                {excelVariables.length > 0 && selectedTemplate.variables.every(v => excelVariables.includes(v.name)) && (
                  <Alert variant="info" className="py-2">
                    <small>
                      Todas las variables se completarán desde el archivo Excel cargado.
                      No es necesario ingresar valores manuales.
                    </small>
                  </Alert>
                )}

                {/* Only show manual input for variables NOT in excelVariables */}
                {selectedTemplate.variables
                  .filter(variable => !excelVariables.includes(variable.name))
                  .map(variable => (
                  <Row key={variable.name} className="mb-3 align-items-center">
                    <Col md={4}>
                      <Form.Label className="mb-0">{variable.name}</Form.Label>
                    </Col>
                    <Col md={8}>
                      <Form.Group>
                        <Form.Control
                          type="text"
                          placeholder={variable.example ? `Ej: ${variable.example}` : `Especifica ${variable.name.toLowerCase()}`}
                          value={formData.templateVariables[variable.name] || ''}
                          onChange={(e) => handleVariableChange(variable.name, e.target.value)}
                          isInvalid={!!errors[`var_${variable.name}`]}
                        />
                        <Form.Control.Feedback type="invalid">
                          {errors[`var_${variable.name}`]}
                        </Form.Control.Feedback>
                      </Form.Group>
                    </Col>
                  </Row>
                ))}
              </div>
            )}

            {/* Button Parameters */}
            {formData.buttonParams && formData.buttonParams.length > 0 && (
              <div className="mb-3">
                <p className="fw-bold text-dark mb-2">Parámetros de botones</p>
                <Alert variant="info" className="py-2">
                  <small>
                    Esta plantilla tiene botones con parámetros dinámicos.
                  </small>
                </Alert>
                {formData.buttonParams.map((btnParam, idx) => (
                  <Row key={idx} className="mb-3 align-items-center">
                    <Col md={4}>
                      <Form.Label className="mb-0">
                        {btnParam.type === 'url' ? 'Sufijo URL dinámica' : 'Código del botón'}
                      </Form.Label>
                    </Col>
                    <Col md={8}>
                      <Form.Group>
                        <Form.Control
                          type="text"
                          placeholder={btnParam.type === 'url' ? 'Ej: parametro-dinamico' : 'Ej: CODIGO123'}
                          value={btnParam.type === 'url' ? btnParam.text : btnParam.code}
                          onChange={(e) => {
                            const newButtonParams = [...formData.buttonParams];
                            if (btnParam.type === 'url') {
                              newButtonParams[idx] = { ...btnParam, text: e.target.value };
                            } else {
                              newButtonParams[idx] = { ...btnParam, code: e.target.value };
                            }
                            setFormData(prev => ({ ...prev, buttonParams: newButtonParams }));
                          }}
                          isInvalid={!!errors[`btn_${idx}`]}
                        />
                        <Form.Control.Feedback type="invalid">
                          {errors[`btn_${idx}`]}
                        </Form.Control.Feedback>
                      </Form.Group>
                    </Col>
                  </Row>
                ))}
              </div>
            )}

            {/* Agent Assignment Section */}
            <div className="mb-3">
              <p className="fw-bold fs-5 text-dark mb-2">Asignación de agentes</p>
              <Alert variant="info" className="py-2">
                <small>
                  Asigna uno o más agentes para recibir las respuestas de esta campaña. Si no asignas ninguno, todos los agentes con acceso a la línea recibirán las respuestas.
                </small>
              </Alert>
              <Row className="mb-3">
                <Col md={12}>
                  <Form.Group>
                    <Form.Check
                      type="checkbox"
                      id="assignToSelf"
                      label="Asignarme a mí mismo"
                      checked={formData.assignToSelf}
                      onChange={(e) => {
                        const checked = e.target.checked;
                        setFormData(prev => ({
                          ...prev,
                          assignToSelf: checked,
                          assignedUserIds: checked ? [] : prev.assignedUserIds
                        }));
                      }}
                      className="mb-2"
                    />
                  </Form.Group>
                </Col>
                {!formData.assignToSelf && (
                  <Col md={12}>
                    <Form.Group>
                      <Form.Label>Agentes (puedes seleccionar varios)</Form.Label>
                      <div className="border rounded p-2" style={{ maxHeight: '200px', overflowY: 'auto' }}>
                        {availableAgents.length === 0 ? (
                          <small className="text-muted">No hay agentes disponibles para esta línea</small>
                        ) : (
                          availableAgents.map(agent => (
                            <Form.Check
                              key={agent.id}
                              type="checkbox"
                              id={`campaign-agent-${agent.id}`}
                              label={`${agent.name} (${agent.email})`}
                              checked={formData.assignedUserIds.includes(agent.id)}
                              onChange={(e) => {
                                if (e.target.checked) {
                                  setFormData(prev => ({
                                    ...prev,
                                    assignedUserIds: [...prev.assignedUserIds, agent.id]
                                  }));
                                } else {
                                  setFormData(prev => ({
                                    ...prev,
                                    assignedUserIds: prev.assignedUserIds.filter(id => id !== agent.id)
                                  }));
                                }
                              }}
                              disabled={formData.assignToSelf}
                              className="mb-2"
                            />
                          ))
                        )}
                      </div>
                      <Form.Text className="text-muted">
                        {formData.assignedUserIds.length > 0
                          ? `${formData.assignedUserIds.length} agente(s) seleccionado(s)`
                          : 'Si no seleccionas ninguno, todos los agentes recibirán las respuestas'
                        }
                      </Form.Text>
                    </Form.Group>
                  </Col>
                )}
              </Row>
            </div>

            {/* Add Recipients Section */}
            <div className="mb-3">
              <div className="d-flex justify-content-between align-items-center mb-2">
                <p className="fw-bold fs-5 text-dark mb-0">Agregar receptores</p>
                <Button
                  variant="outline-primary"
                  size="sm"
                  onClick={() => setShowBulkUpload(true)}
                >
                  <FileEarmarkExcel className="me-2" />
                  Carga masiva
                </Button>
              </div>

              <Row className="mb-2">
                <Col md={5}>
                  <Form.Control
                    type="text"
                    placeholder="Nombre (Opcional)"
                    value={newRecipient.name}
                    onChange={(e) => setNewRecipient(prev => ({ ...prev, name: e.target.value }))}
                  />
                </Col>
                <Col md={5}>
                  <Form.Control
                    type="text"
                    placeholder="Número de teléfono"
                    value={newRecipient.phone}
                    onChange={(e) => setNewRecipient(prev => ({ ...prev, phone: e.target.value }))}
                    isInvalid={!!errors.phone}
                  />
                  <Form.Control.Feedback type="invalid">
                    {errors.phone}
                  </Form.Control.Feedback>
                </Col>
                <Col md={2}>
                  <Button
                    variant="warning"
                    className="w-100"
                    onClick={handleAddRecipient}
                  >
                    Agregar
                  </Button>
                </Col>
              </Row>
            </div>

            {/* Recipients Table */}
            {formData.recipients.length > 0 && (
              <div className="mb-3">
                <div className="table-responsive">
                  <Table striped bordered hover size="sm">
                  <thead className="bg-light">
                    <tr>
                      <th>Nombre del receptor</th>
                      <th>Número telefónico</th>
                      <th>Eliminar</th>
                    </tr>
                  </thead>
                  <tbody>
                    {formData.recipients.map((recipient, index) => (
                      <tr key={index}>
                        <td>{recipient.name || '-'}</td>
                        <td>{recipient.phone}</td>
                        <td className="text-center">
                          <Button
                            variant="link"
                            size="sm"
                            className="text-danger p-0"
                            onClick={() => handleRemoveRecipient(recipient.phone)}
                          >
                            <Trash size={18} />
                          </Button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
                </div>
                <small className="text-muted">
                  Total de receptores: {formData.recipients.length}
                </small>
              </div>
            )}

            {errors.recipients && (
              <Alert
                variant={errors.recipients.includes('duplicado') ? 'info' : 'danger'}
                className="py-2"
              >
                {errors.recipients}
              </Alert>
            )}
          </Form>
        </Modal.Body>

        <Modal.Footer className="border-0">
          <Button variant="outline-dark" onClick={handleClose} disabled={loading}>
            Cancelar
          </Button>
          <Button variant="warning" onClick={handleSubmit} disabled={loading}>
            {loading ? (
              <>
                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                Enviando...
              </>
            ) : (
              <>
                <Send className="me-2" size={16} />
                Enviar mensaje masivo
              </>
            )}
          </Button>
        </Modal.Footer>
      </Modal>

      <BulkUploadModal
        show={showBulkUpload}
        onHide={() => setShowBulkUpload(false)}
        onUpload={handleBulkUpload}
        selectedTemplate={selectedTemplate}
      />
    </>
  );
};

export default CampaignForm;

