/**
 * Bulk Upload Modal Component
 *
 * Modal for uploading recipient lists from CSV/Excel files
 * Supports basic mode (phone + name) and variables mode (with template variables)
 * Based on Figma design node-id: 77-3403
 */

import React, { useState, useEffect } from 'react';
import { Modal, Button, Alert, Form } from 'react-bootstrap';
import { X, Upload, Download, ExclamationTriangle } from 'react-bootstrap-icons';
import campaignService from '../../services/campaignService';

const BulkUploadModal = ({
  show,
  onHide,
  onUpload,
  selectedTemplate = null // Template object with variables array
}) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [fileName, setFileName] = useState('');
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState(null);
  const [parsedCount, setParsedCount] = useState(0);
  const [duplicatesRemoved, setDuplicatesRemoved] = useState(0);

  // New states for variable mode
  const [uploadMode, setUploadMode] = useState('basic'); // 'basic' | 'with_variables'
  const [selectedVariables, setSelectedVariables] = useState([]); // Array of variable names to include
  const [validationErrors, setValidationErrors] = useState([]); // Errors from parsing

  // Get template variables if available
  const templateVariables = selectedTemplate?.variables || [];
  const hasTemplateVariables = templateVariables.length > 0;

  // Reset states when modal opens/closes
  useEffect(() => {
    if (show) {
      // Reset to basic mode when opening
      setUploadMode('basic');
      setSelectedVariables([]);
      setValidationErrors([]);
    } else {
      // Full reset when closing
      setSelectedFile(null);
      setFileName('');
      setError(null);
      setParsedCount(0);
      setDuplicatesRemoved(0);
      setUploadMode('basic');
      setSelectedVariables([]);
      setValidationErrors([]);
    }
  }, [show]);

  // When switching to variables mode, select all variables by default
  useEffect(() => {
    if (uploadMode === 'with_variables' && templateVariables.length > 0) {
      setSelectedVariables(templateVariables.map(v => v.name));
    } else if (uploadMode === 'basic') {
      setSelectedVariables([]);
    }
  }, [uploadMode, templateVariables]);

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      // Validate file type
      const validTypes = [
        'text/csv',
        'application/vnd.ms-excel',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'text/plain'
      ];

      if (!validTypes.includes(file.type) && !file.name.match(/\.(csv|xlsx|xls|txt)$/i)) {
        setError('Formato de archivo no válido. Use CSV, XLSX o TXT');
        return;
      }

      setSelectedFile(file);
      setFileName(file.name);
      setError(null);
      setParsedCount(0);
      setValidationErrors([]);
    }
  };

  const handleRemoveFile = () => {
    setSelectedFile(null);
    setFileName('');
    setError(null);
    setParsedCount(0);
    setDuplicatesRemoved(0);
    setValidationErrors([]);
  };

  const handleVariableToggle = (varName) => {
    setSelectedVariables(prev => {
      if (prev.includes(varName)) {
        return prev.filter(v => v !== varName);
      } else {
        return [...prev, varName];
      }
    });
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setError('Seleccione un archivo primero');
      return;
    }

    // Validate that at least one variable is selected if in variables mode
    if (uploadMode === 'with_variables' && selectedVariables.length === 0) {
      setError('Debe seleccionar al menos una variable para incluir en el Excel');
      return;
    }

    setUploading(true);
    setError(null);
    setValidationErrors([]);

    try {
      // Parse the file with or without expected variables
      const expectedVars = uploadMode === 'with_variables' ? selectedVariables : [];
      const result = await campaignService.parseRecipientsFile(selectedFile, expectedVars);

      const { recipients, errors } = result;

      console.log('Parsed recipients:', recipients);
      console.log('Validation errors:', errors);

      if (recipients.length === 0) {
        setError('El archivo no contiene números válidos');
        setUploading(false);
        return;
      }

      // If there are validation errors (empty variables), show them and block
      if (errors.length > 0) {
        setValidationErrors(errors);
        setError(`Se encontraron ${errors.length} fila(s) con variables vacías. Todas las variables deben estar completas.`);
        setUploading(false);
        return;
      }

      // Clean and validate phone numbers
      const validRecipients = recipients.map(r => ({
        ...r,
        phone: r.phone.replace(/\s+/g, '') // Remove all spaces
      })).filter(r => {
        // Allow + followed by country code and 6-15 digits
        const phoneRegex = /^\+[1-9]\d{5,14}$/;
        return phoneRegex.test(r.phone);
      });

      if (validRecipients.length === 0) {
        setError('Ningún número tiene formato válido. Use formato internacional: +57 3001234567');
        setUploading(false);
        return;
      }

      // Remove duplicates based on phone number
      const uniqueRecipients = [];
      const seenPhones = new Set();
      let duplicatesCount = 0;

      for (const recipient of validRecipients) {
        if (!seenPhones.has(recipient.phone)) {
          seenPhones.add(recipient.phone);
          uniqueRecipients.push(recipient);
        } else {
          duplicatesCount++;
        }
      }

      setParsedCount(uniqueRecipients.length);
      setDuplicatesRemoved(duplicatesCount);

      // Build warning message
      const warnings = [];
      const invalidCount = recipients.length - validRecipients.length;
      if (invalidCount > 0) {
        warnings.push(`${invalidCount} número(s) con formato inválido fueron omitidos`);
      }
      if (duplicatesCount > 0) {
        warnings.push(`${duplicatesCount} número(s) duplicado(s) fueron eliminados`);
      }

      if (warnings.length > 0) {
        setError(warnings.join('. '));
      }

      // Call parent callback with unique recipients and the selected variable names
      onUpload(uniqueRecipients, uploadMode === 'with_variables' ? selectedVariables : []);

      // Reset and close
      handleClose();

    } catch (err) {
      setError(err.message || 'Error al procesar el archivo');
    } finally {
      setUploading(false);
    }
  };

  const handleDownloadTemplate = () => {
    try {
      // If in variables mode, pass the selected variables
      if (uploadMode === 'with_variables' && selectedVariables.length > 0) {
        // Get the full variable objects for the selected ones
        const variablesToInclude = templateVariables.filter(v =>
          selectedVariables.includes(v.name)
        );
        campaignService.downloadTemplate(variablesToInclude);
      } else {
        campaignService.downloadTemplate();
      }
    } catch (err) {
      setError('Error al descargar la plantilla');
    }
  };

  const handleClose = () => {
    setSelectedFile(null);
    setFileName('');
    setError(null);
    setParsedCount(0);
    setDuplicatesRemoved(0);
    setUploadMode('basic');
    setSelectedVariables([]);
    setValidationErrors([]);
    setUploading(false);
    onHide();
  };

  // Check if can use variables mode
  const canUseVariablesMode = selectedTemplate && hasTemplateVariables;

  // Check if upload is allowed
  const canUpload = selectedFile &&
    (uploadMode === 'basic' || (uploadMode === 'with_variables' && selectedVariables.length > 0));

  return (
    <Modal show={show} onHide={handleClose} size="lg" scrollable>
      <Modal.Header className="border-0 pb-0">
        <Modal.Title className="fs-4">Carga masiva</Modal.Title>
        <Button
          variant="link"
          className="text-dark p-0"
          onClick={handleClose}
        >
          <X size={24} />
        </Button>
      </Modal.Header>

      <Modal.Body>
        <div className="mb-4">
          {/* Upload Mode Selection */}
          <div className="mb-4">
            <p className="fw-bold text-dark mb-2">Tipo de carga:</p>
            <Form.Check
              type="radio"
              id="mode-basic"
              name="uploadMode"
              label="Solo contactos (teléfono y nombre)"
              checked={uploadMode === 'basic'}
              onChange={() => setUploadMode('basic')}
              className="mb-2"
            />
            <Form.Check
              type="radio"
              id="mode-variables"
              name="uploadMode"
              label="Con variables de plantilla"
              checked={uploadMode === 'with_variables'}
              onChange={() => setUploadMode('with_variables')}
              disabled={!canUseVariablesMode}
            />
            {!canUseVariablesMode && (
              <small className="text-muted d-block mt-1 ms-4">
                {!selectedTemplate
                  ? 'Primero seleccione una plantilla en el formulario'
                  : 'La plantilla seleccionada no tiene variables'}
              </small>
            )}
          </div>

          {/* Variable Selection (only shown in variables mode) */}
          {uploadMode === 'with_variables' && hasTemplateVariables && (
            <div className="mb-4 p-3 border rounded bg-light">
              <p className="fw-bold text-dark mb-2">Variables a incluir en el Excel:</p>
              <small className="text-muted d-block mb-3">
                Selecciona las variables que deseas completar desde el Excel.
                Las variables no seleccionadas se completarán manualmente en el formulario.
              </small>

              {templateVariables.map(variable => (
                <Form.Check
                  key={variable.name}
                  type="checkbox"
                  id={`var-${variable.name}`}
                  label={
                    <span>
                      <strong>{variable.name}</strong>
                      {variable.example && (
                        <span className="text-muted ms-2">(ej: {variable.example})</span>
                      )}
                    </span>
                  }
                  checked={selectedVariables.includes(variable.name)}
                  onChange={() => handleVariableToggle(variable.name)}
                  className="mb-2"
                />
              ))}

              {selectedVariables.length === 0 && (
                <Alert variant="warning" className="py-2 mt-2 mb-0">
                  <ExclamationTriangle className="me-2" />
                  <small>Debe seleccionar al menos una variable</small>
                </Alert>
              )}

              {selectedVariables.length > 0 && selectedVariables.length < templateVariables.length && (
                <Alert variant="info" className="py-2 mt-2 mb-0">
                  <small>
                    {templateVariables.length - selectedVariables.length} variable(s) se completarán manualmente en el formulario
                  </small>
                </Alert>
              )}
            </div>
          )}

          {/* Download Template Button */}
          <div className="mb-3 d-flex justify-content-between align-items-center">
            <h6 className="mb-0 text-dark">Plantilla de carga</h6>
            <Button
              variant="outline-success"
              size="sm"
              onClick={handleDownloadTemplate}
              disabled={uploading || (uploadMode === 'with_variables' && selectedVariables.length === 0)}
            >
              <Download className="me-2" size={16} />
              Descargar plantilla Excel
            </Button>
          </div>

          <Alert variant="info" className="py-2 mb-3">
            <small>
              <strong>Recomendación:</strong> Descarga la plantilla Excel, llénala con tus datos y súbela aquí.
              La plantilla ya tiene el formato correcto con ejemplos.
            </small>
          </Alert>

          <div className="text-muted mb-3" style={{ lineHeight: 1.5 }}>
            <p className="mb-2 fw-bold">Formato del archivo:</p>
            <ul className="mb-2">
              <li>Primera columna: <strong>Número de Teléfono</strong> (obligatorio) - Debe incluir el prefijo internacional, por ejemplo: <strong>+34 612345678</strong> o <strong>+57 334 5678463</strong></li>
              <li>Segunda columna: <strong>Nombre</strong> (opcional) - Nombre del contacto</li>
              {uploadMode === 'with_variables' && selectedVariables.length > 0 && (
                <li>Columnas adicionales: <strong>{selectedVariables.join(', ')}</strong> (obligatorias)</li>
              )}
              <li>Primera fila: Encabezados (será ignorada automáticamente)</li>
            </ul>
            <p className="mb-2">
              Formatos soportados: .csv, .xlsx o .txt
            </p>
          </div>

          {/* File Input */}
          <div className="d-flex align-items-stretch">
            <Button
              variant="outline-primary"
              className="rounded-end-0"
              onClick={() => document.getElementById('file-input').click()}
              disabled={uploading}
            >
              Elegir archivo
            </Button>
            <Form.Control
              id="file-input"
              type="file"
              accept=".csv,.xlsx,.xls,.txt"
              onChange={handleFileSelect}
              className="d-none"
            />
            <div className="flex-grow-1 border border-start-0 rounded-end px-3 d-flex align-items-center justify-content-between">
              {fileName ? (
                <>
                  <span className="text-muted">{fileName}</span>
                  <Button
                    variant="link"
                    size="sm"
                    className="text-danger p-0"
                    onClick={handleRemoveFile}
                  >
                    <X size={20} />
                  </Button>
                </>
              ) : (
                <span className="text-muted">Ningún archivo seleccionado</span>
              )}
            </div>
          </div>

          {parsedCount > 0 && (
            <Alert variant="success" className="mt-3 py-2 mb-0">
              <small>
                Se encontraron {parsedCount} número(s) válido(s) en el archivo
                {duplicatesRemoved > 0 && ` (${duplicatesRemoved} duplicado(s) eliminados)`}
              </small>
            </Alert>
          )}

          {/* Validation Errors Display */}
          {validationErrors.length > 0 && (
            <Alert variant="danger" className="mt-3 py-2 mb-0">
              <p className="mb-2 fw-bold">
                <ExclamationTriangle className="me-2" />
                Errores de validación ({validationErrors.length}):
              </p>
              <div style={{ maxHeight: '150px', overflowY: 'auto' }}>
                <ul className="mb-0 small">
                  {validationErrors.slice(0, 10).map((err, idx) => (
                    <li key={idx}>
                      Fila {err.row} ({err.phone}): {err.message}
                    </li>
                  ))}
                  {validationErrors.length > 10 && (
                    <li className="text-muted">
                      ... y {validationErrors.length - 10} error(es) más
                    </li>
                  )}
                </ul>
              </div>
            </Alert>
          )}

          {error && validationErrors.length === 0 && (
            <Alert variant="warning" className="mt-3 py-2 mb-0">
              <small>{error}</small>
            </Alert>
          )}
        </div>
      </Modal.Body>

      <Modal.Footer className="border-0">
        <Button variant="outline-dark" onClick={handleClose} disabled={uploading}>
          Volver
        </Button>
        <Button
          variant="warning"
          onClick={handleUpload}
          disabled={!canUpload || uploading}
        >
          {uploading ? (
            <>
              <span className="spinner-border spinner-border-sm me-2" />
              Procesando...
            </>
          ) : (
            <>
              <Upload className="me-2" size={16} />
              Cargar receptores
            </>
          )}
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default BulkUploadModal;

